    let inEscape = false;
    for (const char of querystr) {
        if (inEscape) {
            current += char;
            inEscape = false;
        }
        else if (char === '\\' && inString) {
            current += char;
            inEscape = true;
        }
        else if (char === '"') {
            inString = !inString;
            current += char;
        }
        else if (char === ';' && !inString) {
            const trimmed = current.trim();
            if (trimmed)
                statements.push(trimmed + ';');
            current = '';
        }
        else {
            current += char;
        }
    }
    const trimmed = current.trim();
    if (trimmed)
        statements.push(trimmed + ';');
