    brave: '(?i)(brave)',
    edge: '(?i)^(microsoft[-_ ]?edge|msedge)',
    arc: '(?i)^arc(\\.exe)?$',
    vivaldi: '(?i)(vivaldi)',
    orion: '(?i)(orion)',
    yandex: '(?i)(yandex)',
    zen: '(?i)(zen)',
    floorp: '(?i)(floorp)',
    helium: '(?i)(helium)',
